const out=[new Date().toISOString()];
const n=sdk.getState().nearbyNpcs.filter(x=>/^(Monk of Zamorak|Black Knight|Imp)$/.test(x.name)).sort((a,b)=>a.distance-b.distance)[0];
if(!n) return out.concat(sdk.getState().nearbyNpcs.map(n=>n.name+':'+n.combatLevel));
const r=await bot.attack(n,10000); out.push(n.name+' '+r.message);
for(let i=0;i<80;i++){ if(Date.now()>Date.parse('2026-10-21T15:05:40Z')) break; await new Promise(r=>setTimeout(r,600)); const t=sdk.getNearbyNpc(n.index); if(!t||t.name!==n.name){out.push('gone');break;} }
out.push(new Date().toISOString());
return out;

